WITH lines AS (SELECT id, host, latency_ms, status_code, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS k, attr_value) SELECT CASE WHEN status_code >= 385 THEN 'HIGH' ELSE 'LOW' END AS status_code_tier, k, MAX(status_code) AS max_status_code, COUNT(*) FILTER (WHERE host = 'h1') AS h1_rows, PERCENT_RANK() OVER (PARTITION BY CASE WHEN status_code >= 385 THEN 'HIGH' ELSE 'LOW' END ORDER BY MAX(status_code) DESC) AS max_status_code_percent_rank FROM lines GROUP BY CASE WHEN status_code >= 385 THEN 'HIGH' ELSE 'LOW' END, k;
